// Convert the scene-level maps generated by blender/terrain_tex.py to WebP.
import sharp from 'sharp';
import { mkdirSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'blender', 'textures');
const dst = join(root, 'public', 'textures');
mkdirSync(dst, { recursive: true });

const jobs = [
  ['rumput_c', 1024, 84], ['rumput_n', 512, 90], ['rumput_r', 256, 90],
  ['lumpur_c', 1024, 84], ['lumpur_n', 512, 90], ['lumpur_r', 256, 90],
  ['air_n', 512, 94], ['busa_c', 256, 90],
];
for (const [name, size, quality] of jobs) {
  const out = join(dst, `${name}.webp`);
  await sharp(join(src, `${name}.png`)).resize(size, size).webp({ quality, effort: 6 }).toFile(out);
  console.log(name.padEnd(10), `${(statSync(out).size / 1024).toFixed(0)} KB`);
}
